Great! Now let's move to Phase 2: Database Schema. I'll create the migration for variations:

<write_to_file>
<path>apps/api/src/db/migrations/002_add_variations.ts</path>
<content>import Database from "better-sqlite3";

export const runMigration = (db: Database.Database): void => {
  console.log("Running migration 002_add_variations...");

  // Create game_variations table
  db.exec(`
    CREATE TABLE IF NOT EXISTS game_variations (
      id TEXT PRIMARY KEY,
      profile_id TEXT NOT NULL,
      name TEXT NOT NULL,
      description TEXT NOT NULL,
      difficulty TEXT NOT NULL CHECK (difficulty IN ('easy', 'medium', 'hard')),

      -- Visual customization
      snake_head_image TEXT,

      -- Powerup configuration (stored as JSON)
      max_concurrent_foods INTEGER NOT NULL,
      enabled_powerups TEXT NOT NULL,

      -- Game rules
      base_speed INTEGER NOT NULL,
      base_grid_size INTEGER NOT NULL,

      -- Metadata
      is_public INTEGER NOT NULL DEFAULT 0,
      usage_count INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,

      CHECK (is_public IN (0, 1)),
      CHECK (max_concurrent_foods >= 1 AND max_concurrent_foods <= 5),
      CHECK (base_speed >= 1 AND base_speed <= 30),
      CHECK (base_grid_size >= 8 AND base_grid_size <= 64),

      FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE
    );
  `);

  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_game_variations_profile_id 
    ON game_variations(profile_id);
  `);

  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_game_variations_difficulty 
    ON game_variations(difficulty);
  `);

  // Add variation_id to game_runs
  db.exec(`
    ALTER TABLE game_runs ADD COLUMN variation_id TEXT 
    REFERENCES game_variations(id) ON DELETE SET NULL;
  `);

  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_game_runs_variation_id 
    ON game_runs(variation_id);
  `);

  console.log("Migration 002_add_variations completed successfully.");
};

// Create "Classic" variation for each existing profile
export const createClassicVariations = (db: Database.Database): void => {
  console.log("Creating Classic variations for existing profiles...");

  const profiles = db.prepare("SELECT id FROM profiles").all() as Array<{ id: string }>;

  const insertVariation = db.prepare(`
    INSERT INTO game_variations (
      id, profile_id, name, description, difficulty,
      max_concurrent_foods, enabled_powerups, base_speed, base_grid_size,
      is_public, usage_count, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const now = new Date().toISOString();

  for (const profile of profiles) {
    const classicId = `classic-${profile.id}`;
    const classicPowerup = JSON.stringify([
      {
        id: "default-food",
        name: "Food",
        effect: "add_blocks",
        effectValue: 1,
        color: "#87ae73"
      }
    ]);

    insertVariation.run(
      classicId,
      profile.id,
      "Classic",
      "The original snake game",
      "medium",
      1, // maxConcurrentFoods
      classicPowerup,
      8, // baseSpeed
      20, // baseGridSize
      0, // isPublic
      0, // usageCount
      now,
      now
    );

    // Backfill existing game_runs with classic variation_id
    db.prepare(`
      UPDATE game_runs 
      SET variation_id = ? 
      WHERE profile_id = ? AND variation_id IS NULL
    `).run(classicId, profile.id);

    console.log(`Created Classic variation for profile ${profile.id}`);
  }

  console.log("Classic variations created successfully.");
};
</content>
</write_to_file>

Now create the variation queries:

<write_to_file>
<path>apps/api/src/db/variationQueries.ts</path>
<content>import Database from "better-sqlite3";
import type { GameVariation, GameVariationInput, PowerupType } from "@snake/contracts";

export const createVariationQueries = (db: Database.Database) => {
  const insertVariation = db.prepare(`
    INSERT INTO game_variations (
      id, profile_id, name, description, difficulty,
      snake_head_image, max_concurrent_foods, enabled_powerups,
      base_speed, base_grid_size, is_public, usage_count,
      created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const updateVariation = db.prepare(`
    UPDATE game_variations 
    SET name = ?, description = ?, difficulty = ?,
        snake_head_image = ?, max_concurrent_foods = ?, enabled_powerups = ?,
        base_speed = ?, base_grid_size = ?, is_public = ?, updated_at = ?
    WHERE id = ? AND profile_id = ?
  `);

  const deleteVariation = db.prepare(`
    DELETE FROM game_variations WHERE id = ? AND profile_id = ?
  `);

  const getVariationById = db.prepare(`
    SELECT * FROM game_variations WHERE id = ?
  `);

  const getVariationsByProfile = db.prepare(`
    SELECT * FROM game_variations 
    WHERE profile_id = ? 
    ORDER BY created_at DESC
  `);

  const incrementUsageCount = db.prepare(`
    UPDATE game_variations 
    SET usage_count = usage_count + 1 
    WHERE id = ?
  `);

  const parseVariationRow = (row: any): GameVariation => {
    return {
      id: row.id,
      profileId: row.profile_id,
      name: row.name,
      description: row.description,
      difficulty: row.difficulty,
      snakeHeadImage: row.snake_head_image || undefined,
      maxConcurrentFoods: row.max_concurrent_foods,
      enabledPowerups: JSON.parse(row.enabled_powerups) as PowerupType[],
      baseSpeed: row.base_speed,
      baseGridSize: row.base_grid_size,
      isPublic: row.is_public === 1,
      usageCount: row.usage_count,
      createdAt: row.created_at,
      updatedAt: row.updated_at
    };
  };

  return {
    createVariation: (id: string, profileId: string, input: GameVariationInput): GameVariation => {
      const now = new Date().toISOString();

      insertVariation.run(
        id,
        profileId,
        input.name,
        input.description,
        input.difficulty,
        input.snakeHeadImage || null,
        input.maxConcurrentFoods,
        JSON.stringify(input.enabledPowerups),
        input.baseSpeed,
        input.baseGridSize,
        input.isPublic ? 1 : 0,
        0, // usageCount
        now,
        now
      );

      const row = getVariationById.get(id);
      if (!row) {
        throw new Error("Failed to create variation");
      }

      return parseVariationRow(row);
    },

    updateVariation: (id: string, profileId: string, input: GameVariationInput): GameVariation => {
      const now = new Date().toISOString();

      const result = updateVariation.run(
        input.name,
        input.description,
        input.difficulty,
        input.snakeHeadImage || null,
        input.maxConcurrentFoods,
        JSON.stringify(input.enabledPowerups),
        input.baseSpeed,
        input.baseGridSize,
        input.isPublic ? 1 : 0,
        now,
        id,
        profileId
      );

      if (result.changes === 0) {
        throw new Error("Variation not found or unauthorized");
      }

      const row = getVariationById.get(id);
      if (!row) {
        throw new Error("Failed to retrieve updated variation");
      }

      return parseVariationRow(row);
    },

    deleteVariation: (id: string, profileId: string): void => {
      const result = deleteVariation.run(id, profileId);
      if (result.changes === 0) {
        throw new Error("Variation not found or unauthorized");
      }
    },

    getVariation: (id: string): GameVariation | null => {
      const row = getVariationById.get(id);
      if (!row) return null;
      return parseVariationRow(row);
    },

    getVariationsByProfile: (profileId: string): GameVariation[] => {
      const rows = getVariationsByProfile.all(profileId);
      return rows.map(parseVariationRow);
    },

    incrementUsageCount: (id: string): void => {
      incrementUsageCount.run(id);
    }
  };
};
</content>
</write_to_file>

