import { useTheme as useMuiTheme } from "@mui/material/styles";

export const DesignPage = () => {
  const muiTheme = useMuiTheme();
  const [activeTab, setActiveTab] = useState(0);

  const {
    themes,
    activeTheme,
    loading: themesLoading,
    error: themesError,
    createTheme,
    updateTheme,
    deleteTheme,
